#!/usr/bin/env bash
# Generate tool configs from the Carbon Fiber palette
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
source "$SCRIPT_DIR/colors.sh"

echo "Generating configs from Carbon Fiber palette..."

# --- Ghostty ---
GHOSTTY_CFG="$HOME/.config/ghostty/config"
cat > "$GHOSTTY_CFG" << EOF
# Carbon Fiber — generated by palette/generate.sh
font-family = JetBrainsMono Nerd Font
font-size = 14
font-thicken = true
adjust-cell-height = 15%

background = ${CF_BG}
foreground = ${CF_WHITE}
cursor-color = ${CF_ACCENT}
cursor-style = bar
cursor-style-blink = true
selection-background = ${CF_OVERLAY}
selection-foreground = ${CF_WHITE}

# Terminal palette (0-15)
palette = 0=#${CF_BG}
palette = 1=#${CF_RED}
palette = 2=#${CF_GREEN}
palette = 3=#${CF_YELLOW}
palette = 4=#${CF_BLUE}
palette = 5=#${CF_ACCENT}
palette = 6=#${CF_CYAN}
palette = 7=#${CF_TEXT}
palette = 8=#${CF_DIM}
palette = 9=#${CF_RED}
palette = 10=#${CF_GREEN}
palette = 11=#${CF_YELLOW}
palette = 12=#${CF_BLUE}
palette = 13=#${CF_ACCENT}
palette = 14=#${CF_CYAN}
palette = 15=#${CF_WHITE}

window-padding-x = 16
window-padding-y = 12
window-decoration = false
macos-titlebar-style = hidden
window-theme = dark
copy-on-select = clipboard
confirm-close-surface = false
EOF
echo "  ✓ Ghostty config"

# --- tmux (partial — just colors, append-safe) ---
TMUX_COLORS="$HOME/.config/tmux/carbon-fiber.conf"
cat > "$TMUX_COLORS" << EOF
# Carbon Fiber palette for tmux — source from tmux.conf
set -g status-style "bg=#${CF_SURFACE},fg=#${CF_TEXT}"
set -g status-left-style "bg=#${CF_SURFACE},fg=#${CF_ACCENT}"
set -g status-right-style "bg=#${CF_SURFACE},fg=#${CF_TEXT}"
setw -g window-status-style "bg=#${CF_SURFACE},fg=#${CF_DIM}"
setw -g window-status-current-style "bg=#${CF_OVERLAY},fg=#${CF_WHITE},bold"
set -g pane-border-style "fg=#${CF_BORDER}"
set -g pane-active-border-style "fg=#${CF_ACCENT}"
set -g message-style "bg=#${CF_OVERLAY},fg=#${CF_WHITE}"
set -g message-command-style "bg=#${CF_OVERLAY},fg=#${CF_ACCENT}"
EOF
echo "  ✓ tmux colors"

# --- JankyBorders ---
BORDERS_CFG="$HOME/.config/borders/bordersrc"
cat > "$BORDERS_CFG" << EOF
#!/usr/bin/env bash
# Carbon Fiber — JankyBorders config
borders active_color="0xff${CF_ACCENT}" \
        inactive_color="0xff${CF_BORDER}" \
        width=2.0 \
        style=round
EOF
chmod +x "$BORDERS_CFG"
echo "  ✓ JankyBorders config"

# --- Fastfetch ---
FASTFETCH_CFG="$HOME/.config/fastfetch/config.jsonc"
cat > "$FASTFETCH_CFG" << EOF
{
  "\$schema": "https://github.com/fastfetch-cli/fastfetch/raw/dev/doc/json_schema.json",
  "display": {
    "separator": "  ",
    "color": {
      "keys": "${CF_ACCENT}",
      "output": "${CF_TEXT}"
    }
  },
  "modules": [
    {
      "type": "os",
      "key": "os",
      "keyColor": "${CF_ACCENT}"
    },
    {
      "type": "host",
      "key": "hw",
      "keyColor": "${CF_ACCENT}"
    },
    {
      "type": "uptime",
      "key": "up",
      "keyColor": "${CF_ACCENT}"
    },
    {
      "type": "shell",
      "key": "sh",
      "keyColor": "${CF_ACCENT}"
    },
    {
      "type": "terminal",
      "key": "tm",
      "keyColor": "${CF_ACCENT}"
    },
    {
      "type": "memory",
      "key": "mem",
      "keyColor": "${CF_ACCENT}"
    },
    {
      "type": "disk",
      "key": "dsk",
      "keyColor": "${CF_ACCENT}",
      "folders": "/"
    }
  ]
}
EOF
echo "  ✓ Fastfetch config"

echo ""
echo "Done. Restart tools to apply."
